/** Ordinary launcher folders, shortcut names and Quick Launch, in native Vista chrome. */
final class DesktopOrganizer extends VistaShell {
    interface Host {String label(String id);View icon(String id,int size);void changed();void open(String id);void openFolderWindow(String id);}
    private final Host host;
    private final Supplier<List<AppCatalog.Entry>> apps;
    private ListView currentList;
    private EditText nameInput;
    private final TextView addPrograms;private final LinearLayout crumbs;private String viewMode;
    private String draft,returnPage="desktop";private LinearLayout taskGroup;
    DesktopOrganizer(Context context,DesktopStore store,Actions actions,Host host,Supplier<List<AppCatalog.Entry>> apps,String initial){
        super(context,store,actions,"Search shortcuts");this.host=host;this.apps=apps;
        viewMode=store.prefs.getString("shortcut_folder_view","Medium icons");
        TextView views=command("Views ▾",this::views);addPrograms=command("Add programs",()->navigate("add:"+target()));commands.addView(views,new LayoutParams(-2,dp(36)));commands.addView(addPrograms,new LayoutParams(-2,dp(36)));
        View menu=explorerChrome(this::classicMenu);enableNavigationToggle();revealNavigationPane();
        LinearLayout location=(LinearLayout)address.getParent(),toolbar=(LinearLayout)commands.getParent();int index=location.indexOfChild(address);location.removeView(address);crumbs=new LinearLayout(context);crumbs.setGravity(Gravity.CENTER_VERTICAL);crumbs.setBackground(Aero.panel(context,0xffffffff,0xffffffff,0,0xff7f9db9));crumbs.setContentDescription("Address bar");location.addView(crumbs,index,new LayoutParams(0,dp(28),1));
        toolbar.removeView(search);search.setVisibility(GONE);toolbar.removeView(folders);commands.addView(folders,0,new LayoutParams(dp(65),dp(36)));
        for(TextView nav:new TextView[]{up,forward,back}){((ViewGroup)nav.getParent()).removeView(nav);String kind=nav==back?"back":nav==forward?"forward":"up";nav.setText(nav==back?"Back":"");nav.setTextSize(11);nav.setSingleLine(true);XpNavigation icon=new XpNavigation(context,kind);icon.setBounds(0,0,dp(24),dp(24));nav.setCompoundDrawables(icon,null,null,null);nav.setBackground(Aero.selection(context));commands.addView(nav,0,new LayoutParams(dp(nav==back?68:35),dp(36)));}
        TextView find=command("Search",()->{search.setVisibility(search.getVisibility()==VISIBLE?GONE:VISIBLE);if(search.getVisibility()==VISIBLE)search.requestFocus();else search.setText("");});commands.addView(find,3,new LayoutParams(dp(58),dp(36)));
        toolbar.removeView(commands);HorizontalScrollView tools=new HorizontalScrollView(context);tools.setHorizontalScrollBarEnabled(false);tools.addView(commands);toolbar.addView(tools,new LayoutParams(-1,dp(38)));toolbar.setBackgroundColor(XpTheme.surface(context));location.setBackgroundColor(XpTheme.surface(context));removeView(menu);removeView(toolbar);removeView(location);addView(menu,0);addView(toolbar,1);addView(location,2);addView(search,3,new LayoutParams(-1,dp(32)));menu.setBackgroundColor(XpTheme.surface(context));
        side.setBackground(Aero.panel(context,0xff7ba2e7,0xff6375d6,0,0));start(initial);
    }
    private String target(){String page=page();if(page.startsWith("add:"))return page.substring(4);return page.startsWith("contents:")||page.equals("quick")?page:"desktop";}
    private String folderId(String page){return page.startsWith("contents:")?page.substring(9):null;}
    private List<String> members(String target){String id=folderId(target);return id!=null?store.folderItems(id):target.equals("quick")?store.quickLaunch():store.desktop();}
    private void members(String target,List<String> values){String id=folderId(target);if(id!=null)store.folderItems(id,values);else if(target.equals("quick"))store.quickLaunch(values);else store.desktop(values);}
    @Override void render(){
        currentList=null;nameInput=null;side.removeAllViews();sideHeading("Other Places");folderLink("Desktop shortcuts","computer",()->navigate("desktop"));folderLink("Quick Launch","programs",()->navigate("quick"));folderLink("Desktop Settings","control",()->actions.open("setting:page:icons"));folderLink("Backup and Restore","drive",()->host.open("@backup"));sideHeading("Folders");folderLink("New folder","folderapps",()->{draft=null;navigate("new");});
        JSONObject folders=store.folders();Iterator<String> keys=folders.keys();while(keys.hasNext()){String id=keys.next();LinearLayout link=folderLink(host.label(id),"folderapps",()->openItem(id));
            ContextMenus.bind(link,(x,y)->optionsAt(link,id,"desktop",x,y));
            ContextMenus.bind(link.getChildAt(1),(x,y)->optionsAt(link,id,"desktop",x,y));}
        String page=page();boolean editing=page.equals("new")||page.startsWith("rename:")||page.startsWith("dissolve:");search.setEnabled(!editing);addPrograms.setVisibility(editing?GONE:VISIBLE);updateAddress();
        if(page.equals("new")||page.startsWith("rename:")){editor(page);return;}
        if(page.startsWith("dissolve:")){dissolve(page.substring(9));return;}
        if(page.startsWith("add:")){picker(page.substring(4));return;}
        String folder=folderId(page);address.setText(page.equals("quick")?"Quick Launch":folder==null?"Desktop shortcuts":host.label(folder));
        if(folder!=null&&!store.isFolder(folder)){LinearLayout column=column();heading(column,"Folder removed","Return to Desktop shortcuts to continue browsing.");link(column,"Desktop shortcuts",()->navigate("desktop"));body(scrolling(column));return;}
        List<String> all=members(page),shown=new ArrayList<>();for(String id:all)if(host.label(id).toLowerCase(Locale.getDefault()).contains(query()))shown.add(id);
        LinearLayout column=column();heading(column,page.equals("quick")?"Customize Quick Launch":folder==null?"Arrange your desktop":host.label(folder),folder!=null?"Open a shortcut, or use its menu to rename, reorder or move it.":page.equals("quick")?"Choose up to 12 shortcuts for the taskbar. Hold a taskbar icon for its options.":"Drop a shortcut on the center of another to create a folder. Drop near its edge to swap positions.");
        if(folder!=null){folderContents(page,shown,all.size());return;}
        ListView list=list(column);list.setAdapter(new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int i){return shown.get(i);}public long getItemId(int i){return i;}public View getView(int i,View recycled,ViewGroup parent){String id=shown.get(i);LinearLayout row=row(id);TextView more=Aero.text(getContext(),"⋮",23,Aero.INK);more.setGravity(Gravity.CENTER);more.setContentDescription("Options for "+host.label(id));more.setOnClickListener(v->options(v,id,page));row.addView(more,new LayoutParams(dp(42),dp(52)));row.setOnClickListener(v->openItem(id));ContextMenus.bind(row,(x,y)->optionsAt(row,id,page,x,y));return row;}});
        list.setOnItemClickListener((parent,view,position,id)->{int at=position-list.getHeaderViewsCount();if(at>=0&&at<shown.size())openItem(shown.get(at));});
        list.setOnItemLongClickListener((parent,view,position,id)->{int at=position-list.getHeaderViewsCount();if(at<0||at>=shown.size())return false;options(view,shown.get(at),page);return true;});
        ContextMenus.blank(list,(x,y)->backgroundMenu(list,page,x,y));status.setText(all.size()+" shortcut"+(all.size()==1?"":"s")+(page.equals("quick")?"  •  maximum 12":""));body(list);
    }
    private void sideHeading(String title){taskGroup=XpTaskPane.add(side,title,false).items;}
    private LinearLayout folderLink(String title,String kind,Runnable action){LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(XpControls.menuSelection(getContext()));row.setPadding(dp(2),dp(5),0,dp(5));row.setMinimumHeight(dp(34));row.addView(new AeroIcon(getContext(),kind),new LayoutParams(dp(17),dp(17)));TextView text=command(title,action);text.setGravity(Gravity.CENTER_VERTICAL|Gravity.START);text.setMaxLines(3);text.setTextSize(11);row.addView(text,new LayoutParams(0,-2,1));row.setContentDescription("Navigation: "+title);row.setOnClickListener(v->action.run());taskGroup.addView(row);return row;}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();post(this::updateAddress);}
    private String pageTitle(String value){String id=folderId(value);if(id!=null)return host.label(id);if(value.equals("desktop"))return "Desktop shortcuts";if(value.equals("quick"))return "Quick Launch";if(value.equals("new"))return "New folder";if(value.startsWith("add:"))return "Add programs";if(value.startsWith("rename:"))return "Rename "+host.label(value.substring(7));if(value.startsWith("dissolve:"))return "Dissolve folder";return "Folder options";}
    private String parentPage(String value){
        if(value.equals("desktop"))return null;
        if(value.startsWith("add:"))return value.substring(4);
        if(value.startsWith("dissolve:"))return store.isFolder(value.substring(9))?"contents:"+value.substring(9):"desktop";
        if(value.startsWith("rename:")){String id=value.substring(7);if(store.isFolder(id))return "contents:"+id;if(!returnPage.equals(value))return returnPage;}
        return "desktop";
    }
    private void updateAddress(){
        post(()->{View v=this;while(v.getParent() instanceof View){v=(View)v.getParent();if(v instanceof DesktopWindow){DesktopWindow window=(DesktopWindow)v;String name=pageTitle(page());if(!window.caption().equals(name)){window.caption(name);actions.action("taskbar-refresh");}break;}}});
        crumbs.removeAllViews();HorizontalScrollView scroll=new HorizontalScrollView(getContext());scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);scroll.addView(row);crumbs.addView(scroll,new LayoutParams(-1,-1));
        List<String> chain=new ArrayList<>();String value=page();while(value!=null&&!chain.contains(value)&&chain.size()<8){chain.add(0,value);value=parentPage(value);}
        for(String destination:chain){if(row.getChildCount()>0)row.addView(Aero.text(getContext(),"\\",13,Aero.INK));String label=destination.equals("desktop")?"Desktop":pageTitle(destination);TextView link=command(label,()->navigate(destination));link.setSingleLine(true);link.setContentDescription("Navigate to "+(destination.equals("desktop")?"Desktop shortcuts":label));row.addView(link,new LayoutParams(-2,-1));}scroll.post(()->scroll.fullScroll(View.FOCUS_RIGHT));
    }
    private void folderContents(String target,List<String> items,int total){
        LinearLayout area=Aero.column(getContext());if(viewMode.equals("Details")){LinearLayout header=new LinearLayout(getContext());header.setBackground(Aero.panel(getContext(),0xffffffff,0xffe9eef4,0,0xffbacbd8));TextView name=command("Name ▾",()->sortFolder("Name"));header.addView(name,new LayoutParams(0,dp(28),1));header.addView(command("Type",()->sortFolder("Type")),new LayoutParams(dp(80),dp(28)));header.addView(new View(getContext()),new LayoutParams(dp(40),dp(28)));area.addView(header);}
        if(items.isEmpty()){LinearLayout empty=column();heading(empty,query().isEmpty()?"This folder is empty":"No matching shortcuts",query().isEmpty()?"Add programs to keep related apps together.":"Try another shortcut name.");link(empty,"Add programs…",()->navigate("add:"+target));area.addView(scrolling(empty),new LayoutParams(-1,0,1));}
        else if(viewMode.endsWith("icons")){
            GridView icons=new GridView(getContext());icons.setContentDescription("Organized shortcuts");icons.setColumnWidth(dp(viewMode.equals("Large icons")?110:viewMode.equals("Small icons")?70:86));icons.setNumColumns(GridView.AUTO_FIT);icons.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);icons.setSelector(Aero.selection(getContext()));icons.setAdapter(new BaseAdapter(){public int getCount(){return items.size();}public Object getItem(int i){return items.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){String id=items.get(i);LinearLayout tile=Aero.column(getContext());tile.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);tile.setPadding(dp(4),dp(8),dp(4),dp(3));int size=viewMode.equals("Large icons")?52:viewMode.equals("Small icons")?28:40;tile.addView(host.icon(id,size),new LayoutParams(dp(size),dp(size)));TextView label=Aero.text(getContext(),host.label(id),12,Aero.INK);label.setGravity(Gravity.CENTER);label.setMaxLines(2);label.setEllipsize(TextUtils.TruncateAt.END);tile.addView(label,new LayoutParams(-1,dp(34)));TextView more=command("⋮",()->options(tile,id,target));more.setContentDescription("Options for "+host.label(id));tile.addView(more,new LayoutParams(dp(40),dp(28)));tile.setContentDescription("Shortcut: "+host.label(id));tile.setOnClickListener(v->openItem(id));ContextMenus.bind(tile,(x,y)->optionsAt(tile,id,target,x,y));return tile;}});icons.setOnItemClickListener((p,v,i,id)->openItem(items.get(i)));icons.setOnItemLongClickListener((p,v,i,id)->{options(v,items.get(i),target);return true;});ContextMenus.blank(icons,(x,y)->backgroundMenu(icons,target,x,y));area.addView(icons,new LayoutParams(-1,0,1));
        }else{ListView list=list(new LinearLayout(getContext()));list.setAdapter(new BaseAdapter(){public int getCount(){return items.size();}public Object getItem(int i){return items.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){String id=items.get(i);LinearLayout row=row(id);TextView more=command("⋮",()->options(row,id,target));more.setContentDescription("Options for "+host.label(id));if(viewMode.equals("Details")){TextView type=Aero.text(getContext(),shortcutType(id),11,0xff687c8c);type.setMaxLines(2);type.setEllipsize(TextUtils.TruncateAt.END);row.addView(type,new LayoutParams(dp(80),-2));}row.addView(more,new LayoutParams(dp(40),dp(44)));row.setOnClickListener(v->openItem(id));ContextMenus.bind(row,(x,y)->optionsAt(row,id,target,x,y));return row;}});list.setOnItemClickListener((p,v,i,id)->{int index=i-list.getHeaderViewsCount();if(index>=0&&index<items.size())openItem(items.get(index));});list.setOnItemLongClickListener((p,v,i,id)->{int index=i-list.getHeaderViewsCount();if(index<0||index>=items.size())return false;options(v,items.get(index),target);return true;});ContextMenus.blank(list,(x,y)->backgroundMenu(list,target,x,y));area.addView(list,new LayoutParams(-1,0,1));}
        status.setText((query().isEmpty()?total+(total==1?" shortcut":" shortcuts"):items.size()+" of "+total+" shortcuts")+"  •  App folder");body(area);
    }
    private void showMenu(DesktopContextMenu menu){ContextMenus.centered(commands,(x,y)->ContextMenus.show(menu,commands,x,y));}
    private void views(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Shortcut folder views");for(String mode:new String[]{"Large icons","Medium icons","Small icons","List","Details"})menu.checked(mode,viewMode.equals(mode),()->{viewMode=mode;store.prefs.edit().putString("shortcut_folder_view",mode).apply();render();});menu.separator();menu.checked("Navigation pane",navigationPaneVisible(),this::toggleNavigationPane);showMenu(menu);}
    private void organize(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Organize shortcuts");menu.item("Add programs…","programs",()->navigate("add:"+target()));menu.item("New desktop folder…","folderapps",()->{draft=null;navigate("new");});menu.item("Paste","paste",!ExplorerClipboard.shortcuts.isEmpty(),()->paste(target()));String folder=folderId(target());if(store.isFolder(folder)){menu.separator();folderCommands(menu,folder);menu.item("Rename folder","notes",()->rename(folder));menu.item("Dissolve folder…","folderapps",()->navigate("dissolve:"+folder));}showMenu(menu);}
    private String shortcutType(String id){return store.isFolder(id)?"App folder":id.startsWith("@")?"Nth Desktop tool":"Android app";}
    private void sortFolder(String mode){List<String> values=members(target());java.text.Collator order=java.text.Collator.getInstance();values.sort((a,b)->mode.equals("Type")&&!shortcutType(a).equals(shortcutType(b))?order.compare(shortcutType(a),shortcutType(b)):order.compare(host.label(a),host.label(b)));members(target(),values);host.changed();render();}
    private void classicMenu(String label){DesktopContextMenu menu=new DesktopContextMenu(getContext(),label+" menu");switch(label){case "File":folderCommands(menu,folderId(target()));menu.item("Add programs…","programs",()->navigate("add:"+target()));menu.item("New desktop folder…","folderapps",()->{draft=null;navigate("new");});menu.item("Folder properties","control",()->Aero.dialog(getContext()).setTitle("Folder properties").setMessage(members(target()).size()+" launcher shortcuts. Use each shortcut’s menu for Cut, Copy, Rename or Move. Removing a shortcut keeps its installed app.").setPositiveButton("OK",null).show());menu.item("Close","close",this::closeWindow);break;case "Edit":menu.item("Paste","paste",!ExplorerClipboard.shortcuts.isEmpty(),()->paste(target()));menu.item("Add or remove programs…","programs",()->navigate("add:"+target()));break;case "View":menu.submenu("Views","appearance",this::views);menu.item("Sort by name","programs",()->sortFolder("Name"));menu.item("Sort by type","programs",()->sortFolder("Type"));menu.checked("Navigation pane",navigationPaneVisible(),this::toggleNavigationPane);menu.item("Refresh","refresh",this::refreshApps);break;case "Tools":menu.item("Desktop Settings","control",()->actions.open("setting:page:icons"));menu.item("Backup and Restore","drive",()->host.open("@backup"));break;case "Help":menu.item("App folder help","folderapps",()->Aero.dialog(getContext()).setTitle("App folders").setMessage("Use Add programs to choose shortcuts. Tap to open, or hold an icon for Cut, Copy, Rename and Move. Views changes the icon or list layout. Folders shows or hides the remembered navigation pane. Back, Forward, Up and the address links navigate your shortcut folders.").setPositiveButton("OK",null).show());break;}showMenu(menu);}
    private void closeWindow(){View v=this;while(v.getParent() instanceof View){v=(View)v.getParent();if(v instanceof DesktopWindow){clickClose(v);return;}}}
    private boolean clickClose(View v){if("Close window".equals(v.getContentDescription())){v.performClick();return true;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(clickClose(((ViewGroup)v).getChildAt(i)))return true;return false;}
    private void backgroundMenu(View anchor,String target,float x,float y){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"App folder context menu");menu.item("Paste","paste",!ExplorerClipboard.shortcuts.isEmpty(),()->paste(target));menu.submenu("Views","appearance",this::views);menu.item("Sort by name","programs",()->sortFolder("Name"));menu.item("New desktop folder…","folderapps",()->{draft=null;navigate("new");});menu.item("Add programs","programs",()->navigate("add:"+target));menu.item("Refresh","refresh",this::refreshApps);ContextMenus.show(menu,anchor,x,y);}
    private void picker(String target){
        String folder=folderId(target);if(folder!=null&&!store.isFolder(folder)){navigate("desktop");return;}address.setText("Add programs  ›  "+(folder!=null?host.label(folder):target.equals("quick")?"Quick Launch":"Desktop"));
        List<String> available=new ArrayList<>(Arrays.asList("@computer","@browser","@photos",MediaLibrary.PLAYER,MediaLibrary.CENTER,"@files","@notes","@appearance","@control","@calendar","@sticky","@filemanagers","@backup","@taskmanager","@recycle","@workspaces","@recent"));
        Iterator<String> locations=FolderLinks.list(store).keys();while(locations.hasNext())available.add(locations.next());for(AppCatalog.Entry app:apps.get())if(!available.contains(app.id))available.add(app.id);
        if(folder==null){Iterator<String> keys=store.folders().keys();while(keys.hasNext())available.add(keys.next());}
        available.sort((a,b)->java.text.Collator.getInstance().compare(host.label(a),host.label(b)));available.removeIf(id->!host.label(id).toLowerCase(Locale.getDefault()).contains(query()));
        LinearLayout column=column();heading(column,"Choose shortcuts","Checked items appear in "+(folder!=null?host.label(folder):target.equals("quick")?"Quick Launch":"your desktop")+".");link(column,"Done",()->navigate(target));ListView list=list(column);List<String> chosen=members(target);
        list.setAdapter(new BaseAdapter(){public int getCount(){return available.size();}public Object getItem(int i){return available.get(i);}public long getItemId(int i){return i;}public View getView(int i,View recycled,ViewGroup parent){String id=available.get(i);LinearLayout row=row(id);CheckBox box=Aero.check(getContext(),"",false);box.setFocusable(false);box.setChecked(chosen.contains(id));box.setContentDescription("Include "+host.label(id));box.setOnCheckedChangeListener((v,checked)->select(target,id,checked));row.addView(box,new LayoutParams(dp(48),dp(52)));row.setOnClickListener(v->select(target,id,!members(target).contains(id)));ContextMenus.bind(row,(x,y)->optionsAt(row,id,target,x,y));return row;}});
        list.setOnItemClickListener((parent,view,position,id)->{int at=position-list.getHeaderViewsCount();if(at>=0&&at<available.size()){String item=available.get(at);select(target,item,!members(target).contains(item));}});status.setText(chosen.size()+" selected");body(list);
    }
    private void select(String target,String id,boolean include){List<String> current=members(target);if(include==current.contains(id))return;if(include){int max=target.equals("quick")?DesktopStore.MAX_QUICK:target.startsWith("contents:")?DesktopStore.MAX_ITEMS:512;if(current.size()>=max){Toast.makeText(getContext(),"This list holds up to "+max+" shortcuts",Toast.LENGTH_SHORT).show();refreshApps();return;}current.add(id);}else current.remove(id);members(target,current);host.changed();}
    private ListView list(LinearLayout header){ListView list=new ListView(getContext());list.setDividerHeight(0);list.setSelector(Aero.selection(getContext()));list.setContentDescription("Organized shortcuts");list.addHeaderView(header,null,false);currentList=list;return list;}
    private LinearLayout row(String id){LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),dp(3),dp(4),dp(3));row.addView(host.icon(id,30),new LayoutParams(dp(30),dp(30)));LinearLayout text=Aero.column(getContext());text.setPadding(dp(11),dp(6),0,dp(6));TextView name=Aero.text(getContext(),host.label(id),13,Aero.INK);name.setMaxLines(2);text.addView(name);if(store.isFolder(id))text.addView(Aero.text(getContext(),store.folderItems(id).size()+" shortcuts",10,0xff687c8c));row.addView(text,new LayoutParams(0,dp(52),1));row.setContentDescription("Shortcut: "+host.label(id));return row;}
    private void openItem(String id) {
        if (store.isFolder(id)) navigate("contents:"+id);
        else host.open(id);
    }
    private void deleteItem(String id, String source) {
        RecycleBin.trashShortcut(getContext(),store,source,id,host.label(id));
        host.changed();
    }
    private void folderCommands(DesktopContextMenu menu, String folder) {
        if (!store.isFolder(folder)) return;
        menu.item("Open in new window","folderapps",()->host.openFolderWindow(folder));
        menu.item("Delete folder","delete",()->deleteItem(folder,"desktop"));
    }
    private void options(View anchor,String id,String target){ContextMenus.centered(anchor,(x,y)->optionsAt(anchor,id,target,x,y));}
    private void optionsAt(View anchor,String id,String target,float x,float y){
        DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Shortcut context menu");menu.item("Open","programs",()->openItem(id));boolean folder=store.isFolder(id);if(folder)menu.item("Open in new window","folderapps",()->host.openFolderWindow(id));menu.separator();menu.item("Cut","cut",members(target).contains(id),()->{ExplorerClipboard.shortcuts(Collections.singletonList(id),target,true);status.setText("Shortcut cut. Choose a destination and Paste.");});menu.item("Copy","copy",()->{ExplorerClipboard.shortcuts(Collections.singletonList(id),target,false);status.setText("Shortcut copied. Choose a destination and Paste.");});String destination=store.isFolder(id)?"contents:"+id:target;menu.item("Paste","paste",!ExplorerClipboard.shortcuts.isEmpty(),()->paste(destination));menu.separator();menu.item(folder?"Delete folder":"Delete shortcut","delete",(folder||members(target).contains(id))&&!id.equals("@recycle"),()->deleteItem(id,target));menu.item("Rename","notes",()->rename(id));List<String> current=members(target);int index=current.indexOf(id);menu.item("Move up","programs",index>0,()->shift(target,id,-1));menu.item("Move down","programs",index>=0&&index<current.size()-1,()->shift(target,id,1));
        if(target.startsWith("contents:"))menu.item("Move to desktop","computer",()->{List<String> desktop=store.desktop();if(!desktop.contains(id))desktop.add(id);store.desktop(desktop);List<String> items=members(target);items.remove(id);members(target,items);host.changed();});
        if(!target.equals("quick"))menu.item("Add to Quick Launch","programs",()->select("quick",id,true));if(!folder)menu.item(target.equals("quick")?"Remove from Quick Launch":target.equals("desktop")?"Remove from desktop":"Remove from folder","delete",()->{if(id.equals("@recycle"))select(target,id,false);else{RecycleBin.trashShortcut(getContext(),store,target,id,host.label(id));host.changed();}});if(store.isFolder(id))menu.item("Dissolve folder…","folderapps",()->navigate("dissolve:"+id));else menu.item("Restore original name","notes",()->{store.originalName(id);host.changed();});ContextMenus.show(menu,anchor,x,y);
    }
    private void paste(String target){try{ExplorerClipboard.paste(store,target);host.changed();render();}catch(IllegalArgumentException ex){Toast.makeText(getContext(),ex.getMessage(),Toast.LENGTH_LONG).show();}}
    private void shift(String target,String id,int direction){List<String> current=members(target);store.shift(current,id,direction);members(target,current);host.changed();}
    void rename(String id){draft=null;returnPage=page();navigate("rename:"+id);}
    private void editor(String page){
        boolean creating=page.equals("new");String id=creating?null:page.substring(7);LinearLayout column=column();address.setText(creating?"New folder":"Rename shortcut");heading(column,creating?"Create a desktop folder":"Choose a name",creating?"Keep related apps together in a folder.":"The new name is used throughout your launcher.");
        nameInput=new EditText(getContext());nameInput.setTypeface(Aero.face(getContext()));nameInput.setSingleLine(true);nameInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(40)});nameInput.setContentDescription(creating||store.isFolder(id)?"Folder name":"Shortcut name");nameInput.setText(draft!=null?draft:creating?"New folder":host.label(id));nameInput.setSelectAllOnFocus(true);column.addView(nameInput,new LayoutParams(-1,dp(48)));nameInput.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){draft=s.toString();}public void afterTextChanged(Editable e){}});
        TextView save=Aero.button(getContext(),creating?"Create folder":"Save name",()->{String name=DesktopStore.cleanName(nameInput.getText().toString());if(name.isEmpty()){nameInput.setError("Enter a name");return;}try{String result=id;if(creating)result=store.createFolder(name,Collections.emptyList());else store.rename(id,name);draft=null;((android.view.inputmethod.InputMethodManager)getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(nameInput.getWindowToken(),0);host.changed();navigate(creating||store.isFolder(id)?"contents:"+result:returnPage);}catch(IllegalArgumentException error){nameInput.setError(error.getMessage());}});save.setContentDescription(creating?"Create folder":"Save shortcut name");column.addView(save,new LayoutParams(-1,dp(44)));status.setText("Names can contain up to 40 characters");body(scrolling(column));
    }
    private void dissolve(String id){LinearLayout column=column();address.setText("Dissolve folder");heading(column,"Dissolve "+host.label(id)+"?","Its "+store.folderItems(id).size()+" shortcuts will return to the desktop. Your installed apps are kept.");TextView confirm=Aero.button(getContext(),"Move shortcuts to desktop",()->{store.dissolve(id);host.changed();navigate("desktop");});confirm.setContentDescription("Confirm dissolve folder");column.addView(confirm,new LayoutParams(-1,dp(46)));link(column,"Keep folder",()->navigate("contents:"+id));status.setText("Review before changing the folder");body(scrolling(column));}
    @Override void refreshApps(){String folder=folderId(target());if(folder!=null&&!store.isFolder(folder)){navigate("desktop");return;}int position=currentList==null?0:currentList.getFirstVisiblePosition(),offset=currentList==null||currentList.getChildCount()==0?0:currentList.getChildAt(0).getTop();render();if(currentList!=null)currentList.setSelectionFromTop(position,offset);}
    @Override void showFolders(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Folder navigation");for(String page:Arrays.asList("desktop","quick"))menu.item(page.equals("quick")?"Quick Launch":"Desktop shortcuts","folderapps",()->navigate(page));Iterator<String> keys=store.folders().keys();while(keys.hasNext()){String id=keys.next();menu.item(host.label(id),"folderapps",()->navigate("contents:"+id));}ContextMenus.centered(folders,(x,y)->ContextMenus.show(menu,folders,x,y));}
    @Override boolean canGoUp(){return parentPage(page())!=null;}
    @Override void goUp(){String parent=parentPage(page());if(parent!=null)navigate(parent);}
    @Override JSONObject extraState(){JSONObject saved=new JSONObject();if(draft!=null)GadgetLayout.put(saved,"nameDraft",draft);GadgetLayout.put(saved,"returnPage",returnPage);GadgetLayout.put(saved,"view",viewMode);return saved;}
    @Override void restoreExtra(JSONObject saved){draft=saved!=null&&saved.has("nameDraft")?saved.optString("nameDraft"):null;returnPage=saved==null?"desktop":saved.optString("returnPage","desktop");if(saved!=null)viewMode=saved.optString("view",viewMode);}
}
